mapper.codeEditorJavascript:
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const titles=(input.sheets||[]).map(s=>String((s.properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
for(let k=-1;k<=0;k++){const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+k,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(titles.includes(t)) tabs.push(t);}
return {count:tabs.length, body: JSON.stringify({dataFilters: tabs.map(t=>({a1Range:"'"+t+"'!A1:AC3000"})), valueRenderOption:'FORMATTED_VALUE'})};

// inputs: cf (ManyChat custom fields array), wa, name, choice, ranges (Pelephone month tabs valueRanges)
const TZ = 'Asia/Jerusalem';
const fmt = new Intl.DateTimeFormat('en-US', {timeZone: TZ, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short'});
function ilParts(t) { const o = {}; for (const p of fmt.formatToParts(new Date(t))) o[p.type] = p.value; return {y: +o.year, m: +o.month - 1, d: +o.day, h: +o.hour % 24, mi: +o.minute, wd: ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(o.weekday)}; }
function ilToUtc(y, m, d, h, mi) { const want = Date.UTC(y, m, d, h, mi); let t = want; for (let i = 0; i < 3; i++) { const p = ilParts(t); t += want - Date.UTC(p.y, p.m, p.d, p.h, p.mi); } return t; }
const pad = n => String(n).padStart(2, '0');
const norm = s => String(s || '').replace(/\s+/g, ' ').trim();
const DAYS = ['ראשון', 'שני', 'שלישי', 'רביעי', 'חמישי', 'שישי', 'שבת'];

const cf = {}; for (const f of (input.cf || [])) { if (f && f.name) cf[f.name] = f.value; }
let wa = String(input.wa || '').replace(/\D/g, ''); if (wa.startsWith('0')) wa = '972' + wa.slice(1);
const local9 = wa.startsWith('972') ? wa.slice(3) : wa.replace(/^0/, '');
const phone = '0' + local9;
const full = norm(cf['לקוח פלאפון'] || cf['שם לקוח'] || input.name);
const rep = norm(cf['נציג פלאפון']);
let repWa = String(cf['טלפון נציג פלאפון'] || '').replace(/\D/g, '');
let choice = norm(input.choice); if (!choice || choice.includes(String.fromCharCode(123,123))) choice = norm(cf['זמן חזרה פלאפון']);

// ---------- understand the requested time ----------
const now = Date.now();
const np = ilParts(now);
function plan(text) {
  let c = ' ' + text.replace(/\d{5,}/g, ' ').replace(/[״"׳']/g, '') + ' ';
  let dayOffset = null, explicitDay = false, h = null, mi = 0;
  // explicit date d.m or d/m
  const dm = c.match(/(\d{1,2})\s*[./]\s*(\d{1,2})(?:\s*[./]\s*\d{2,4})?/);
  let target = null;
  if (dm) {
    const d = +dm[1], m = +dm[2] - 1;
    if (d >= 1 && d <= 31 && m >= 0 && m <= 11) {
      let y = np.y; if (Date.UTC(y, m, d) < Date.UTC(np.y, np.m, np.d) - 60 * 864e5) y++;
      target = {y, m, d}; explicitDay = true;
    }
    c = c.replace(dm[0], ' ');
  }
  if (!target) {
    if (/מחרתיים/.test(c)) { dayOffset = 2; explicitDay = true; }
    else if (/מחר/.test(c)) { dayOffset = 1; explicitDay = true; }
    else if (/היום|הערב(?!\S)/.test(c)) { dayOffset = 0; explicitDay = true; }
    else {
      for (let i = 0; i < 7; i++) {
        if (new RegExp('יום\\s*' + DAYS[i] + '(?!\\S)').test(c) || new RegExp('\\s' + DAYS[i] + '\\s').test(c)) {
          dayOffset = (i - np.wd + 7) % 7; explicitDay = true; break;
        }
      }
    }
  }
  // time
  const hm = c.match(/(\d{1,2})\s*:\s*(\d{2})/);
  const evening = /ערב/.test(c), morningWord = /בוקר/.test(c), noonWord = /אחה|אחר הצהריים|צהריים|צהרים/.test(c);
  if (hm) { h = +hm[1]; mi = +hm[2]; }
  else {
    const bare = c.match(/(?:^|[^\d])(\d{1,2})(?![\d:./])/);
    if (bare) { h = +bare[1]; mi = 0; }
  }
  if (h !== null) {
    if (evening && h < 12) h += 12;
    else if (!morningWord && h >= 1 && h <= 7) h += 12;
    if (h > 23 || mi > 59) return null;
  } else if (/עכשיו|מיידי|מייד|כעת/.test(c)) {
    h = 'now';
  } else if (morningWord) { h = 10; mi = 0; }
  else if (noonWord) { h = 17; mi = 30; }
  else return null;

  let base;
  if (target) base = target;
  else { const off = dayOffset || 0; const t = new Date(Date.UTC(np.y, np.m, np.d + off)); base = {y: t.getUTCFullYear(), m: t.getUTCMonth(), d: t.getUTCDate()}; }
  let when;
  if (h === 'now') when = now;
  else when = ilToUtc(base.y, base.m, base.d, h, mi);
  if (when < now - 5 * 60e3) {
    if (explicitDay) return null;          // asked for a day/time that already passed
    when = ilToUtc(base.y, base.m, base.d + 1, h, mi);   // today's slot passed -> tomorrow
  }
  // never on Shabbat -> Sunday same time (or 10:00 for "now")
  let wp = ilParts(when);
  if (wp.wd === 6) {
    const hh = h === 'now' ? 10 : h, mm = h === 'now' ? 0 : mi;
    when = ilToUtc(wp.y, wp.m, wp.d + 1, hh, mm); wp = ilParts(when);
  }
  if (when < now) when = now;
  wp = ilParts(when);
  const todayKey = Date.UTC(np.y, np.m, np.d), wKey = Date.UTC(wp.y, wp.m, wp.d);
  const diff = Math.round((wKey - todayKey) / 864e5);
  const dayTxt = diff === 0 ? 'היום' : diff === 1 ? 'מחר' : 'ביום ' + DAYS[wp.wd] + ' ' + pad(wp.d) + '/' + pad(wp.m + 1);
  return {iso: new Date(when).toISOString(), text: dayTxt + ' ב-' + pad(wp.h) + ':' + pad(wp.mi)};
}
const sched = choice ? plan(choice) : null;

// ---------- find the customer in the Pelephone sales sheet ----------
// RULE (15/11/2026, כפילויות): אותו טלפון בכמה שורות - שורה בלי מספר לקוח לא דורסת שורה שכבר נמצאה עם מספר לקוח. Do not remove.
let tab = '', row = 0, custNum = '', qty = 0;
for (const vr of (input.ranges || [])) {
  const t = String((vr.valueRange || {}).range || '').split('!')[0].replace(/^'|'$/g, '');
  const vals = (vr.valueRange && vr.valueRange.values) || [];
  for (let i = 1; i < vals.length; i++) {
    let p = String(vals[i][3] || '').replace(/\D/g, ''); if (p.startsWith('972')) p = p.slice(3); p = p.replace(/^0/, '');
    if (p && p === local9 && !(/\d/.test(custNum) && !/\d/.test(String(vals[i][9] || '')))) { tab = t; row = i + 1; custNum = norm(vals[i][9]); qty = parseInt(vals[i][14], 10) || 0; }
  }
}
custNum = custNum.replace(/[^\d]/g, '');

const st = 'direction:rtl;font-family:Aptos,Aptos_EmbeddedFont,Aptos_MSFontService,Calibri,Helvetica,sans-serif;font-size:12pt;color:rgb(0,0,0)';
const lines = ['רוצה לנייד עכשיו בבקשה' + (qty > 1 ? ' ' + qty + ' קווים' : ''), 'לחייג ל-' + phone];
const html = lines.map(l => '<div style="' + st + '">' + l + '</div>').join('') +
  '<div style="' + st + '"><br /></div><div id="Signature"><p style="direction:rtl;margin-top:1em;margin-bottom:1em"><b>ירדן בן שלוש</b></p>' +
  '<p style="direction:rtl;margin-top:1em;margin-bottom:1em">מנכ”ל - יהל תקשורת</p>' +
  '<p style="direction:rtl;margin-top:1em;margin-bottom:1em">פתרונות תקשורת מתקדמים | משווק מורשה yes</p></div>';

let base = 'לקוח פלאפון קיבל את הסימים ומחכה לניוד\nשם: ' + full + '\nטלפון: ' + phone + '\nמתי לחזור אליו: *' + (choice || 'לא צוין') + '*';
if (!/^9725\d{8}$/.test(repWa)) { base = 'לא מצאתי בלשונית יעדים טלפון של הנציג "' + (rep || 'לא ידוע') + '"\n\n' + base; repWa = '972544604246'; }
else base = 'היי ' + rep.split(' ')[0] + ',\n' + base;

return {
  key: wa, phone, full, rep, repWa, choice, base,
  canSchedule: !!(sched && custNum), reason: !sched ? 'time' : (!custNum ? 'custnum' : ''),
  sendAt: sched ? sched.iso : '', sendAtText: sched ? sched.text : '',
  custNum, subject: custNum, html, tab, row
};

// RULE (Steve, 14/10/2026): a customer's reply NEVER sends/schedules a porting email by itself.
// The email to niyudim@pelephone.co.il goes out only after the rep approves via the bot: "ניוד <phone> <time>".
const prev = String(input.prevStatus || '').trim();
const prevText = String(input.prevText || '').trim();
const already = prev === 'sent' || prev === 'sending';
const phone = String(input.phone || '').trim();
let line;
if (already) line = '\nכבר שלחנו מייל לניודים על הלקוח הזה (' + prevText + ').';
else {
  line = '\nהמייל לניודים *לא* יוצא לבד, רק אחרי שתאשר.\nתדבר עם הלקוח, תתאם שעה ותשלח לבוט:\nניוד ' + phone + ' <שעה>';
  if (input.reason === 'custnum') line += '\nשים לב, לא מצאתי מספר לקוח בדוח מכר פלאפון.';
}
return {schedule: false, msg: String(input.base || '') + line};
